svg.script:
(function () {
  var script = document.currentScript;
  var svg = script && (script.ownerSVGElement || (script.closest ? script.closest('svg') : null));

  if (!svg && document.documentElement && document.documentElement.nodeName.toLowerCase() === 'svg') {
    svg = document.documentElement;
  }

  if (!svg || typeof svg.createSVGPoint !== 'function') {
    return;
  }

  var eyes = Array.prototype.slice.call(svg.querySelectorAll('.eye-track'));
  if (!eyes.length) {
    return;
  }

  var doc = svg.ownerDocument || document;
  var win = doc.defaultView || window;
  if (win.matchMedia && !win.matchMedia('(pointer: fine)').matches) {
    return;
  }

  var point = svg.createSVGPoint();
  var frameId = null;
  var resetTimer = null;

  function readNumber(node, name, fallback) {
    var value = parseFloat(node.getAttribute(name));
    return isNaN(value) ? fallback : value;
  }

  var state = eyes.map(function (eye) {
    return {
      node: eye,
      centerX: readNumber(eye, 'data-eye-x', 0),
      centerY: readNumber(eye, 'data-eye-y', 0),
      maxX: readNumber(eye, 'data-eye-max-x', 4.5),
      maxY: readNumber(eye, 'data-eye-max-y', 3.2),
      currentX: 0,
      currentY: 0,
      targetX: 0,
      targetY: 0
    };
  });

  function render() {
    var shouldContinue = false;

    state.forEach(function (eye) {
      eye.currentX += (eye.targetX - eye.currentX) * 0.18;
      eye.currentY += (eye.targetY - eye.currentY) * 0.18;

      if (Math.abs(eye.targetX - eye.currentX) > 0.01 || Math.abs(eye.targetY - eye.currentY) > 0.01) {
        shouldContinue = true;
      }

      eye.node.setAttribute(
        'transform',
        'translate(' + eye.currentX.toFixed(2) + ' ' + eye.currentY.toFixed(2) + ')'
      );
    });

    frameId = shouldContinue ? win.requestAnimationFrame(render) : null;
  }

  function queueRender() {
    if (frameId === null) {
      frameId = win.requestAnimationFrame(render);
    }
  }

  function resetEyes() {
    state.forEach(function (eye) {
      eye.targetX = 0;
      eye.targetY = 0;
    });
    queueRender();
  }

  function scheduleReset() {
    if (resetTimer !== null) {
      win.clearTimeout(resetTimer);
    }
    resetTimer = win.setTimeout(function () {
      resetTimer = null;
      resetEyes();
    }, 140);
  }

  function updateTargets(clientX, clientY) {
    var ctm = svg.getScreenCTM();
    if (!ctm) {
      return;
    }

    point.x = clientX;
    point.y = clientY;

    var local = point.matrixTransform(ctm.inverse());

    state.forEach(function (eye) {
      var dx = local.x - eye.centerX;
      var dy = local.y - eye.centerY;
      var angle = Math.atan2(dy, dx);
      var strength = Math.min(1, Math.hypot(dx, dy) / 120);

      eye.targetX = Math.cos(angle) * eye.maxX * strength;
      eye.targetY = Math.sin(angle) * eye.maxY * strength;
    });

    queueRender();
  }

  function handlePointerMove(event) {
    if (event.pointerType === 'touch') {
      return;
    }

    if (resetTimer !== null) {
      win.clearTimeout(resetTimer);
      resetTimer = null;
    }

    updateTargets(event.clientX, event.clientY);
  }

  function handlePointerOut(event) {
    if (!event.relatedTarget) {
      scheduleReset();
    }
  }

  doc.addEventListener('pointermove', handlePointerMove, { passive: true });
  doc.addEventListener('pointerout', handlePointerOut, { passive: true });
  win.addEventListener('blur', resetEyes);
})();
